/* Coiff'Match – styles de l'application et des formulaires (compte, contact).
   Tout est préfixé (.cm-app, .cm-account, .cm-form…) pour ne pas toucher au reste du site. */

.cm-app, .cm-account, .cm-form, .cm-notice, .cm-legal, .cm-delete, .cm-pro-intro {
  --bg: #F0F2EE; --surface: #FFFFFF; --line: #D5DBD5; --fg: #10201D; --muted: #55635F;
  --accent: #0B2A27; --accent-ink: #F0F2EE; --accent-soft: #E3EAE6; --link: #0E5754; --gold: #E2B864; --gold-soft: #F3E9D2;
  --warn: #8A4B12; --warn-soft: #FBEBDD; --ok: #2F6B2F; --ok-soft: #E3F1E1;
  --ph1: #C9A88F; --ph2: #8E6F5C; --ph3: #5E4A3F; --ph4: #A9876F;
  --display: 'DM Sans', 'Segoe UI', system-ui, sans-serif; --serif: 'Gloock', 'Iowan Old Style', Georgia, serif;
  --body: 'DM Sans', 'Segoe UI', system-ui, sans-serif;
}

/* ---------------- Application ---------------- */
.cm-app { max-width: 620px; margin: 0 auto; color: var(--fg); font-family: var(--body); font-size: 16px; line-height: 1.45; position: relative; }
.cm-app *, .cm-app *::before, .cm-app *::after { box-sizing: border-box; }
.cm-app h1, .cm-app h2, .cm-app h3 { font-family: var(--display); color: var(--fg); margin: 0; line-height: 1.15; text-wrap: balance; }
.cm-app h1 { font-size: 26px; } .cm-app h2 { font-size: 19px; }
.cm-app p { margin: 0; }
.cm-app ul { margin: 0; padding: 0; list-style: none; }
.cm-app [hidden] { display: none !important; }
.cm-app .sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }
.cm-app .small { font-size: 12px; }
.cm-loading { color: var(--muted); padding: 24px 0; }

/* Remise à zéro des boutons / champs du thème */
.cm-app button, .cm-app button:hover, .cm-app button:focus { font: inherit; font-weight: 600; text-transform: none; letter-spacing: normal; line-height: 1.2; box-shadow: none; text-decoration: none; color: var(--fg); background: var(--surface); border: 1.5px solid var(--line); border-radius: 12px; padding: 0 12px; margin: 0; cursor: pointer; }
.cm-app button:disabled { opacity: .45; cursor: not-allowed; }
.cm-app :focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.cm-app select, .cm-app input, .cm-app textarea { font: inherit; color: var(--fg); min-height: 46px; border: 1.5px solid var(--line); border-radius: 12px; background: var(--surface); padding: 0 12px; width: 100%; box-shadow: none; margin: 0; }
.cm-app textarea { padding: 10px 12px; min-height: 90px; resize: vertical; }
.cm-app input[type=checkbox] { width: 18px; height: 18px; min-height: 0; padding: 0; accent-color: var(--accent); }
.cm-app fieldset.plain { border: 0; padding: 0; margin: 0; min-width: 0; }
.cm-app legend { padding: 0; margin-bottom: 6px; }

.cm-app .top { position: sticky; top: 0; z-index: 5; background: var(--bg); padding: 10px 0; border-bottom: 1px solid var(--line); }
.admin-bar .cm-app .top { top: 32px; }
.cm-app .tabs { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
.cm-app .tabs button, .cm-app .tabs button:hover { min-height: 44px; font-size: 14px; padding: 0 4px; display: flex; align-items: center; justify-content: center; gap: 4px; }
.cm-app .tabs button[aria-current=page] { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.cm-app .badge { display: inline-flex; min-width: 20px; height: 20px; padding: 0 6px; border-radius: 999px; background: var(--warn); color: #fff; font-size: 12px; align-items: center; justify-content: center; }

.cm-app .view { display: flex; flex-direction: column; gap: 18px; padding: 18px 0 24px; }
.cm-app .lead { font-size: 32px; line-height: 1.1; }
.cm-app .label { font-size: 14px; font-weight: 600; color: var(--muted); }
.cm-app .chips { display: flex; flex-wrap: wrap; gap: 8px; }
.cm-app .chip, .cm-app .chip:hover { min-height: 44px; padding: 0 16px; border-radius: 999px; }
.cm-app .chip.sm, .cm-app .chip.sm:hover { min-height: 40px; padding: 0 12px; font-size: 14px; }
.cm-app .chip[aria-checked=true], .cm-app .chip[aria-pressed=true] { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.cm-app .row { display: flex; gap: 10px; flex-wrap: wrap; }
.cm-app .field { flex: 0 0 auto; display: flex; flex-direction: column; gap: 6px; min-width: 0; margin: 0; }
.cm-app .row > .field { flex: 1 1 160px; }
.cm-app .count { font-size: 14px; color: var(--muted); }
.cm-app .count strong { color: var(--fg); }
.cm-app .list { display: flex; flex-direction: column; gap: 12px; }
.cm-app .cardwrap { position: relative; }
.cm-app .card, .cm-app .card:hover { display: flex; gap: 12px; padding: 10px; width: 100%; text-align: left; border: 1px solid var(--line); border-radius: 18px; font-weight: 400; align-items: stretch; }
.cm-app .card:hover { border-color: var(--accent); }
.cm-app .heart, .cm-app .heart:hover { position: absolute; top: 8px; right: 8px; width: 40px; height: 40px; padding: 0; border-radius: 999px; border: 1px solid var(--line); display: flex; align-items: center; justify-content: center; color: var(--muted); }
.cm-app .heart[aria-pressed=true] { color: var(--warn); }
.cm-app .ph { flex: none; display: block; border-radius: 12px; position: relative; overflow: hidden; background: var(--c, var(--ph1)); }
.cm-app .ph.pattern::after { content: ""; position: absolute; inset: 0; background: radial-gradient(circle at 30% 30%, rgba(255,255,255,.18) 0 18%, transparent 19%), radial-gradient(circle at 65% 55%, rgba(255,255,255,.14) 0 22%, transparent 23%), radial-gradient(circle at 40% 80%, rgba(255,255,255,.12) 0 15%, transparent 16%); }
.cm-app .ph img { width: 100%; height: 100%; object-fit: cover; display: block; }
.cm-app .card .ph { width: 92px; height: 108px; }
.cm-app .meta { display: flex; flex-direction: column; gap: 3px; min-width: 0; justify-content: center; padding-right: 40px; }
.cm-app .name { font-weight: 600; font-size: 17px; }
.cm-app .sub { font-size: 14px; color: var(--muted); font-weight: 400; }
.cm-app .price { font-weight: 600; color: var(--accent); }
.cm-app .pill { display: inline-flex; align-items: center; gap: 4px; font-size: 12px; font-weight: 600; padding: 3px 10px; border-radius: 999px; background: var(--accent-soft); color: var(--accent); white-space: nowrap; }
.cm-app .pill.grey { background: var(--line); color: var(--muted); } .cm-app .pill.ok { background: var(--ok-soft); color: var(--ok); } .cm-app .pill.warn { background: var(--warn-soft); color: var(--warn); }
.cm-app .tags { display: flex; flex-wrap: wrap; gap: 6px; }
.cm-app .tags li { font-size: 13px; font-weight: 600; padding: 5px 12px; border-radius: 999px; background: var(--accent-soft); color: var(--accent); }
.cm-app .who { display: flex; gap: 14px; align-items: center; }
.cm-app .avatar { width: 68px; height: 68px; border-radius: 999px; }
.cm-app #cm-p-body { display: flex; flex-direction: column; gap: 18px; }
.cm-app .gallery { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
.cm-app .gallery .ph { height: 130px; }
.cm-app .stack { display: flex; flex-direction: column; gap: 8px; }
.cm-app .opt, .cm-app .opt:hover { display: flex; justify-content: space-between; align-items: center; gap: 12px; padding: 12px 14px; border-radius: 14px; text-align: left; width: 100%; font-weight: 400; min-height: 56px; }
.cm-app .opt[aria-checked=true] { border-color: var(--accent); background: var(--accent-soft); }
.cm-app .quote { margin: 0; padding: 14px; background: var(--surface); border: 1px solid var(--line); border-radius: 14px; display: flex; flex-direction: column; gap: 6px; font-size: 15px; font-style: normal; quotes: none; }
.cm-app .quote::before, .cm-app .quote::after { content: none; }
.cm-app .quote footer { font-size: 13px; color: var(--muted); }
.cm-app .reply { border-left: 3px solid var(--accent); padding-left: 10px; font-size: 14px; }
.cm-app .days { display: flex; gap: 6px; overflow-x: auto; padding-bottom: 4px; scroll-snap-type: x mandatory; }
.cm-app .days .slot { flex: 0 0 64px; scroll-snap-align: start; }
.cm-app .grid4 { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 6px; }
.cm-app .slot, .cm-app .slot:hover { min-height: 50px; padding: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; font-variant-numeric: tabular-nums; }
.cm-app .slot small { font-weight: 500; font-size: 12px; }
.cm-app .slot[aria-pressed=true] { background: var(--accent); border-color: var(--accent); color: var(--accent-ink); }
.cm-app .slot.taken { opacity: .5; text-decoration: line-through; }
.cm-app .box { background: var(--surface); border: 1px solid var(--line); border-radius: 16px; padding: 14px; display: flex; flex-direction: column; gap: 8px; }
.cm-app .l { display: flex; justify-content: space-between; gap: 10px; font-size: 15px; font-variant-numeric: tabular-nums; }
.cm-app .sep { border-top: 1px solid var(--line); padding-top: 8px; }
.cm-app .note { display: flex; gap: 8px; font-size: 14px; color: var(--muted); }
.cm-app .bar { position: sticky; bottom: 0; background: var(--bg); padding: 12px 0 14px; border-top: 1px solid var(--line); z-index: 3; }
.cm-app .cta, .cm-app .cta:hover { width: 100%; min-height: 52px; border: 0; border-radius: 14px; background: var(--accent); color: var(--accent-ink); font-size: 16px; }
.cm-app .cta:hover:not(:disabled) { filter: brightness(1.12); }
.cm-app .cta-link { display: inline-flex; min-height: 48px; align-items: center; padding: 0 18px; border-radius: 12px; background: var(--accent); color: var(--accent-ink) !important; font-weight: 600; text-decoration: none !important; }
.cm-app .ghost, .cm-app .ghost:hover { min-height: 46px; padding: 0 16px; border: 1.5px solid var(--accent); background: transparent; color: var(--accent); display: inline-flex; align-items: center; justify-content: center; }
.cm-app .link, .cm-app .link:hover { background: none; border: 0; color: var(--accent); padding: 8px 0; min-height: 44px; }
.cm-app .danger, .cm-app .danger:hover { color: var(--warn); }
.cm-app .iconbtn, .cm-app .iconbtn:hover { width: 44px; height: 44px; flex: none; padding: 0; border-radius: 999px; border: 1px solid var(--line); display: inline-flex; align-items: center; justify-content: center; }
.cm-app .iconbtn.primary, .cm-app .iconbtn.primary:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.cm-app .head { display: flex; align-items: center; gap: 10px; }
.cm-app .done { align-items: center; text-align: center; padding-top: 40px; }
.cm-app .tick { width: 76px; height: 76px; border-radius: 999px; background: var(--accent); display: flex; align-items: center; justify-content: center; color: var(--accent-ink); }
.cm-app .msg { padding: 12px 14px; border-radius: 12px; background: var(--warn-soft); font-size: 14px; }
.cm-app .msg.ok { background: var(--ok-soft); }
.cm-app .err { color: var(--warn); font-size: 14px; font-weight: 600; }
.cm-app .empty { padding: 20px; text-align: center; color: var(--muted); background: var(--surface); border: 1px dashed var(--line); border-radius: 16px; }
.cm-app .rdv { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 12px 14px; display: flex; flex-direction: column; gap: 6px; }
.cm-app .actions { display: flex; gap: 4px 18px; flex-wrap: wrap; align-items: center; }
.cm-app .stars { display: flex; gap: 6px; }
.cm-app .star, .cm-app .star:hover { width: 48px; height: 48px; padding: 0; font-size: 22px; }
.cm-app .star[aria-pressed=true] { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.cm-app .stats { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px; }
.cm-app .stat { background: var(--surface); border: 1px solid var(--line); border-radius: 14px; padding: 12px; font-size: 14px; color: var(--muted); }
.cm-app .stat b { display: block; font-family: var(--display); font-size: 26px; color: var(--fg); font-variant-numeric: tabular-nums; }
.cm-app .prow { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 12px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); }
.cm-app .prow .full { grid-column: 1 / -1; }
.cm-app .dayrow { display: flex; flex-direction: column; gap: 8px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); }
.cm-app .dayhead { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.cm-app .dayhead .sub { flex: 1; }
.cm-app .check-inline { display: inline-flex; align-items: center; gap: 8px; min-height: 40px; cursor: pointer; }
.cm-app .hgrid { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; }
.cm-app .hgrid .chip, .cm-app .hgrid .chip:hover { padding: 0; }
.cm-app .thumbs { display: flex; flex-wrap: wrap; gap: 8px; }
.cm-app .thumb { position: relative; width: 92px; height: 92px; border-radius: 10px; overflow: hidden; background: var(--line); }
.cm-app .thumb img { width: 100%; height: 100%; object-fit: cover; }
.cm-app .thumb button, .cm-app .thumb button:hover { position: absolute; top: 4px; right: 4px; width: 30px; height: 30px; min-height: 0; padding: 0; border-radius: 999px; border: 0; background: rgba(0,0,0,.65); color: #fff; }
.cm-app .thread { display: flex; flex-direction: column; gap: 8px; min-height: 260px; max-height: 60vh; overflow-y: auto; padding: 4px 2px; }
.cm-app .bubble { max-width: 80%; padding: 10px 12px; border-radius: 14px; background: var(--surface); border: 1px solid var(--line); align-self: flex-start; display: flex; flex-direction: column; gap: 4px; overflow-wrap: anywhere; }
.cm-app .bubble.mine { align-self: flex-end; background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
.cm-app .bubble time { font-size: 11px; opacity: .8; }
.cm-app .composer { display: flex; gap: 8px; align-items: flex-end; }
.cm-app .composer textarea { min-height: 48px; height: 48px; }
.cm-app .inline { display: flex; flex-direction: column; gap: 8px; padding: 12px; border: 1.5px dashed var(--line); border-radius: 12px; background: var(--surface); }
.cm-app .toast { position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%); background: var(--fg); color: var(--bg); padding: 10px 16px; border-radius: 12px; font-weight: 600; z-index: 9999; max-width: 90vw; }
@media (max-width: 480px) { .cm-app .tabs button, .cm-app .tabs button:hover { font-size: 13px; } .cm-app .lead { font-size: 27px; } .cm-app .hgrid { grid-template-columns: repeat(4, minmax(0, 1fr)); } .cm-app .gallery .ph { height: 104px; } }
@media (prefers-reduced-motion: no-preference) { .cm-app .view { animation: cmIn .18s ease-out; } @keyframes cmIn { from { transform: translateY(6px); opacity: .6; } to { transform: none; opacity: 1; } } }

/* ---------------- Compte et contact ---------------- */
.cm-account { max-width: 900px; margin: 0 auto; font-family: var(--body); color: var(--fg); }
.cm-account h2 { font-family: var(--display); margin: 0 0 12px; }
.cm-account__grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 20px; }
.cm-account__links { list-style: none; padding: 0; margin: 16px 0; display: flex; flex-wrap: wrap; gap: 10px; }
.cm-card { background: var(--surface, #fff); border: 1px solid var(--line, #E6DBD0); border-radius: 18px; padding: 22px; }
.cm-form { display: flex; flex-direction: column; gap: 14px; font-family: var(--body); max-width: 640px; }
.cm-form label { display: flex; flex-direction: column; gap: 6px; font-weight: 600; font-size: 14px; color: var(--muted); }
.cm-form input[type=text], .cm-form input[type=email], .cm-form input[type=password], .cm-form textarea { font: inherit; color: var(--fg); min-height: 46px; border: 1.5px solid var(--line); border-radius: 12px; background: #fff; padding: 0 12px; width: 100%; box-sizing: border-box; font-weight: 400; }
.cm-form textarea { padding: 10px 12px; }
.cm-form .cm-check, .cm-radios label { flex-direction: row; align-items: center; gap: 8px; font-weight: 400; color: var(--fg); }
.cm-form input[type=checkbox], .cm-form input[type=radio] { accent-color: var(--accent); width: 18px; height: 18px; }
.cm-radios { border: 0; padding: 0; margin: 0; display: flex; gap: 18px; flex-wrap: wrap; }
.cm-radios legend { font-weight: 600; font-size: 14px; color: var(--muted); margin-bottom: 6px; }
.cm-hp { position: absolute !important; left: -9999px !important; }
.cm-btn, .cm-form button[type=submit] { display: inline-flex; align-items: center; justify-content: center; min-height: 48px; padding: 0 20px; border-radius: 12px; border: 1.5px solid var(--accent); background: var(--accent); color: #fff !important; font: inherit; font-weight: 600; text-decoration: none !important; cursor: pointer; }
.cm-btn--ghost { background: transparent; color: var(--accent) !important; }
.cm-notice { padding: 12px 14px; border-radius: 12px; font-family: var(--body); margin: 0 0 16px; }
.cm-notice--ok { background: var(--ok-soft); color: var(--ok); }
.cm-notice--err { background: var(--warn-soft); color: var(--warn); font-weight: 600; }

.cm-form__note { font-size: 13px; color: var(--muted); margin: 0; }
.cm-form button.cm-btn--danger, .cm-btn--danger { background: #9B2C1F !important; border-color: #9B2C1F !important; }
.cm-form .cm-check { align-items: flex-start; }
.cm-form .cm-check input { flex: none; margin-top: 2px; }
.cm-form .cm-check span { display: block; }
.cm-delete { margin-top: 32px; padding: 16px 22px; }
.cm-delete summary { cursor: pointer; font-weight: 600; color: var(--muted); min-height: 32px; display: flex; align-items: center; }
.cm-delete[open] summary { margin-bottom: 12px; color: var(--fg); }
.cm-delete p { color: var(--muted); }

/* ---------------- Pages légales ---------------- */
.cm-legal { font-family: var(--body); color: var(--fg); line-height: 1.6; }
.cm-legal h2 { font-family: var(--display); font-size: 1.3em; margin: 1.8em 0 .5em; }
.cm-legal ul { padding-left: 1.2em; }
.cm-legal li { margin: .3em 0; }
.cm-legal .cm-todo { background: #FFF1B8; color: #6B4E00; padding: 0 4px; border-radius: 4px; }
.cm-legal__table { width: 100%; border-collapse: collapse; font-size: 15px; margin: 1em 0; display: block; overflow-x: auto; }
.cm-legal__table th, .cm-legal__table td { text-align: left; vertical-align: top; padding: 10px 12px; border-bottom: 1px solid var(--line); min-width: 140px; }
.cm-legal__table th { background: var(--bg); font-weight: 600; }
.cm-legal__date { color: var(--muted); margin-top: 2em; }

/* ---------------- 1.2 : lieu, agenda, filtres, partage ---------------- */
.cm-app .where { display: flex; flex-direction: column; gap: 2px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); }
.cm-app .where a, .cm-app .cal a, .cm-app .rdv a { color: var(--accent); font-weight: 600; }
.cm-app .cal { display: block; font-size: 14px; line-height: 1.6; }
.cm-app .done .cal { text-align: center; margin: 4px 0 8px; }
.cm-app .selchip { display: inline-flex; align-items: center; padding: 0 4px 0 0; }
.cm-app .selchip select { min-height: 36px; border: 0; background: transparent; font-weight: 600; font-size: 14px; padding: 0 8px; width: auto; }
.cm-app .share { align-items: center; }
.cm-app .share input { flex: 1; min-width: 0; font-size: 14px; }
.cm-app .share button { flex: none; min-height: 46px; padding: 0 16px; }
.cm-app label.selchip { border: 1.5px solid var(--line); border-radius: 999px; background: var(--surface); min-height: 40px; cursor: pointer; }
.cm-app label.selchip:focus-within { outline: 3px solid var(--accent); outline-offset: 2px; }
/* ---------------- 1.3 : espaces séparés ---------------- */
.cm-app .tabs--3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.cm-app #cm-roleNote { margin-top: 12px; }
.cm-app #cm-roleNote a { color: var(--accent); font-weight: 600; }
.cm-app a.ghost { display: inline-flex; align-items: center; justify-content: center; min-height: 48px; padding: 0 18px; border: 1.5px solid var(--accent); border-radius: 12px; color: var(--accent); font-weight: 600; text-decoration: none; }
.cm-pro-intro { margin: 0 0 20px; max-width: 640px; }
.cm-pro-intro h2 { font-family: var(--display); margin: 0 0 8px; }
.cm-pro-intro p { color: var(--muted); margin: 0; }
.cm-account__switch { margin-top: 18px; color: var(--muted); font-family: var(--body); }
.cm-account__switch a { color: var(--accent); font-weight: 600; }
/* ---------------- 2.0 : diagnostic, prochaine dispo, agenda, clientes ---------------- */
.cm-app .tex { flex: none; width: 44px; height: 44px; border-radius: 10px; background: var(--bg) center / 80% no-repeat; border: 1px solid var(--line); }
.cm-app .tex--raides { background-image: url('hair/raides.svg'); }
.cm-app .tex--ondules { background-image: url('hair/ondules.svg'); }
.cm-app .tex--boucles { background-image: url('hair/boucles.svg'); }
.cm-app .tex--frises { background-image: url('hair/frises.svg'); }
.cm-app .tex--crepus { background-image: url('hair/crepus.svg'); }
.cm-app #cm-diag-opts .opt { justify-content: flex-start; gap: 14px; min-height: 64px; }
.cm-app .progress { height: 6px; border-radius: 999px; background: var(--line); overflow: hidden; }
.cm-app .progress span { display: block; height: 100%; background: var(--accent); transition: width .25s ease; }
.cm-app .diagbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap; padding: 12px 14px; border-radius: 14px; background: var(--accent-soft); color: var(--fg); font-size: 15px; }
.cm-app .diagbar .link { color: var(--accent); font-weight: 700; }
.cm-app .ghost.sm, .cm-app .ghost.sm:hover { min-height: 40px; padding: 0 14px; }
