.cm-pub { --ink: #0B2A27; --ink-2: #123A36; --paper: #F0F2EE; --gold: #E2B864; --gold-soft: #F3E9D2; --line: #D5DBD5; --fg: #10201D; --muted: #55635F; --link: #0E5754; --surface: #FFFFFF;
