    t.appendChild(s); t.appendChild(m); a.appendChild(img); a.appendChild(t); row.appendChild(a);
  });
  box.hidden = false;
})();

/* Barre de progression : chaque clic qui charge une page, ou chaque échange avec l'application, se voit tout de suite. */
(function () {
  var bar = document.createElement('div');
  bar.className = 'cm-progress'; bar.setAttribute('aria-hidden', 'true');
  document.body.appendChild(bar);
  var t = 0, on = false;
  function start() {
    if (on) return; on = true; clearTimeout(t);
    bar.style.transition = 'none'; bar.style.opacity = '1'; bar.style.transform = 'scaleX(0)';
    void bar.offsetWidth;
    bar.style.transition = 'transform 8s cubic-bezier(.1, .9, .2, 1)'; bar.style.transform = 'scaleX(.9)';
  }
  function done() {
    if (!on) return; on = false;
    bar.style.transition = 'transform .2s ease, opacity .3s ease .15s'; bar.style.transform = 'scaleX(1)'; bar.style.opacity = '0';
  }
  document.addEventListener('cm:busy', function () { clearTimeout(t); t = setTimeout(start, 120); });
  document.addEventListener('cm:idle', function () { clearTimeout(t); done(); });
  window.addEventListener('click', function (e) {
    var a = e.target.closest && e.target.closest('a[href]');
    if (!a || e.defaultPrevented || e.button !== 0 || e.metaKey || e.ctrlKey || e.shiftKey || a.target === '_blank' || a.hasAttribute('download')) return;
    var u; try { u = new URL(a.href, location.href); } catch (x) { return; }
    if (u.origin !== location.origin || (u.pathname === location.pathname && u.search === location.search && u.hash)) return;
    if (/^(mailto|tel|sms):/.test(a.href)) return;
    start();
  });
  window.addEventListener('submit', function (e) { if (!e.defaultPrevented) start(); });
  window.addEventListener('pageshow', done);
})();

/**
 * Coiff'Match – les mèches de l'accueil : de gauche à droite, chaque mèche passe
 * du raide au crépu. Elles ondulent doucement et s'écartent au passage de la souris.
 * Mouvement désactivé si l'utilisateur a demandé moins d'animations.
 */
(function () {
	var c = document.querySelector('.hero3__strands');
	if (!c || !c.getContext) return;
	var g = c.getContext('2d');
	var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
	var mouse = { x: -9999, y: -9999 };
	var raf = 0, visible = true;

	function size() {
		var dpr = Math.min(window.devicePixelRatio || 1, 2);
		c.width = Math.round(c.clientWidth * dpr);
		c.height = Math.round(c.clientHeight * dpr);
		g.setTransform(dpr, 0, 0, dpr, 0, 0);
	}

	function draw(t) {
		var w = c.clientWidth, h = c.clientHeight;
		g.clearRect(0, 0, w, h);
		var narrow = w < 760;
		var left = narrow ? w * 0.05 : w * 0.46;
		var span = narrow ? w * 1.0 : w * 0.6;
		var n = narrow ? 34 : 72;
		var bottom = (narrow || /band/.test(c.parentElement.className)) ? h + 10 : h * 0.86;
		for (var i = 0; i < n; i++) {
			var u = i / (n - 1);
			var x0 = left + u * span;
			var amp = 1.5 + u * u * 15;
			var freq = 0.004 + u * u * 0.085;
			var sway = Math.sin(t / 1500 + i * 0.33) * 7;
			g.beginPath();
			for (var y = -10; y <= bottom; y += 3) {
				var x = x0 + sway * (y / h) + Math.sin(y * freq + i) * amp;
				if (u > 0.82) x += ((Math.floor(y / 5) % 2) ? 1 : -1) * (u - 0.82) * 14;
				var dx = x - mouse.x, dy = y - mouse.y, d2 = dx * dx + dy * dy;
				if (d2 < 14400) x += (dx >= 0 ? 1 : -1) * (1 - d2 / 14400) * 18;
				if (y === -10) g.moveTo(x, y); else g.lineTo(x, y);
			}
			var gold = i % 7 === 3;
			g.strokeStyle = gold ? 'rgba(226, 184, 100, ' + (narrow ? 0.4 : 0.85) + ')' : 'rgba(240, 242, 238, ' + (narrow ? 0.05 + 0.08 * u : 0.1 + 0.2 * u) + ')';
			g.lineWidth = gold ? 1.8 : 1.4;
			g.stroke();
		}
		if (!reduce && visible) raf = requestAnimationFrame(draw);
	}

	size();
	window.addEventListener('resize', function () { size(); if (reduce) draw(0); });
	c.parentElement.addEventListener('pointermove', function (e) {
		var r = c.getBoundingClientRect();
		mouse.x = e.clientX - r.left; mouse.y = e.clientY - r.top;
	});
	c.parentElement.addEventListener('pointerleave', function () { mouse.x = mouse.y = -9999; });
	if ('IntersectionObserver' in window) {
		new IntersectionObserver(function (es) {
			visible = es[0].isIntersecting;
			if (visible && !reduce) { cancelAnimationFrame(raf); raf = requestAnimationFrame(draw); }
		}).observe(c);
	}
	draw(0);
	if (!reduce) raf = requestAnimationFrame(draw);
})();

/* Coiff'Match – thème. Couleurs et polices du prototype. */
:root {
  /* Piste « signature » : nuit vert profond, papier gris-vert, or pour les moments clés. */
  --ink: #0B2A27; --ink-2: #123A36; --paper: #F0F2EE; --on-ink: #F0F2EE; --on-ink-muted: #A9BAB5;
  --bg: #F0F2EE; --surface: #FFFFFF; --line: #D5DBD5; --fg: #10201D; --muted: #55635F;
  --accent: #0E5754; --accent-2: #0A403E; --accent-ink: #FFFFFF; --accent-soft: #DCEDE8;
  --gold: #E2B864; --gold-ink: #7A5714; --gold-soft: #F3E9D2;
  --serif: 'Gloock', 'Iowan Old Style', Georgia, serif;
  --warm: #8A4B12; --warm-soft: #FBEBDD; --ok: #2F6B2F; --ok-soft: #E3F1E1;
  --ph1: #C9A88F; --ph2: #8E6F5C; --ph3: #5E4A3F;
  --display: 'DM Sans', 'Segoe UI', system-ui, sans-serif;
  --body: 'DM Sans', 'Segoe UI', system-ui, sans-serif;
  --radius: 18px;
}

*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body { margin: 0; background: var(--bg); color: var(--fg); font-family: var(--body); font-size: 17px; line-height: 1.55; }
img { max-width: 100%; height: auto; }
a { color: var(--accent); text-underline-offset: 3px; }
a:hover { color: var(--accent-2); }
h1, h2, h3, h4 { font-family: var(--display); line-height: 1.12; margin: 0 0 .5em; text-wrap: balance; }
h1, h2 { font-family: var(--serif); font-weight: 400; letter-spacing: -.01em; }
h1 { font-size: clamp(36px, 5vw, 58px); line-height: 1.02; }
h2 { font-size: clamp(28px, 3.4vw, 42px); line-height: 1.06; }
h3 { font-size: 20px; }
p { margin: 0 0 1em; }
:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.skip-link { position: absolute; left: -9999px; top: 8px; background: var(--fg); color: #fff; padding: 8px 14px; border-radius: 8px; z-index: 100; }
.skip-link:focus { left: 8px; }
.center { text-align: center; }

.wrap { width: 100%; max-width: 1140px; margin: 0 auto; padding: 0 20px; }
.wrap--narrow { max-width: 760px; }

/* Boutons */
.btn, .wp-block-button__link { display: inline-flex; align-items: center; justify-content: center; min-height: 50px; padding: 0 24px; border-radius: 14px; background: var(--accent); color: var(--accent-ink) !important; font-weight: 600; text-decoration: none; border: 1.5px solid var(--accent); transition: background .15s; }
.btn:hover, .wp-block-button__link:hover { background: var(--accent-2); border-color: var(--accent-2); }
.btn--small { min-height: 42px; padding: 0 16px; border-radius: 12px; font-size: 15px; }
.btn--ghost { background: transparent; color: var(--accent) !important; }
.btn--ghost:hover { background: var(--accent-soft); }
.btn--light { background: #fff; color: var(--accent) !important; border-color: #fff; }
.btn--light:hover { background: var(--accent-soft); }
.pill { display: inline-flex; font-size: 12px; font-weight: 600; padding: 3px 10px; border-radius: 999px; background: var(--ok-soft); color: var(--ok); width: fit-content; }

/* En-tête */
.site-header { position: sticky; top: 0; z-index: 50; background: var(--ink); color: var(--on-ink); border-bottom: 1px solid rgba(240, 242, 238, .12); }
.home .site-header { position: absolute; left: 0; right: 0; background: transparent; border-bottom-color: transparent; }
.admin-bar .site-header { top: 32px; }
.site-header__inner { display: flex; align-items: center; gap: 16px; min-height: 70px; }
.brand { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--on-ink); margin-right: auto; }
.brand:hover { color: var(--on-ink); }
.brand__mark { display: inline-flex; width: 34px; height: 34px; border-radius: 999px; background: var(--gold); color: var(--ink); align-items: center; justify-content: center; font-size: 16px; }
.brand__name { font-family: var(--serif); font-weight: 400; font-size: 27px; }
.brand__logo { max-height: 44px; width: auto; }
.site-nav { display: flex; align-items: center; gap: 22px; }
.site-nav .menu { display: flex; gap: 22px; list-style: none; margin: 0; padding: 0; }
.site-nav .menu a { color: var(--on-ink); text-decoration: none; font-weight: 500; }
.site-nav .menu a:hover, .site-nav .current-menu-item > a { color: var(--gold); }
.site-nav__pro { color: var(--gold) !important; background: transparent !important; border-color: transparent !important; padding: 0 6px !important; }
.site-nav__pro:hover { text-decoration: underline; }
.site-nav__account { background: var(--gold) !important; border-color: var(--gold) !important; color: var(--ink) !important; border-radius: 999px !important; }
.site-nav__account:hover { background: #EDCB86 !important; }
.site-header__toggle { display: none; background: none; border: 1.5px solid rgba(240, 242, 238, .3); border-radius: 12px; width: 46px; height: 46px; cursor: pointer; }
.burger, .burger::before, .burger::after { display: block; width: 20px; height: 2px; background: var(--on-ink); margin: 0 auto; position: relative; content: ""; }
.burger::before { position: absolute; top: -6px; } .burger::after { position: absolute; top: 6px; }
@media (max-width: 860px) {
  .site-header__toggle { display: inline-block; }
  .site-nav { display: none; position: absolute; left: 0; right: 0; top: 100%; background: var(--ink); border-bottom: 1px solid rgba(240, 242, 238, .12); flex-direction: column; align-items: stretch; padding: 12px 20px 20px; gap: 8px; }
  .site-nav.is-open { display: flex; }
  .site-nav .menu { flex-direction: column; gap: 0; }
  .site-nav .menu a { display: block; padding: 12px 0; border-bottom: 1px solid rgba(240, 242, 238, .12); }
  .site-nav__account, .site-nav__pro { margin-top: 8px; }
}
@media (max-width: 782px) { .admin-bar .site-header { top: 46px; } }

.site-main { min-height: 60vh; }

/* Accueil */
.hero2 { padding: 48px 0 56px; }
.hero2__top { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr); gap: 40px; align-items: end; margin-bottom: 36px; }
.hero2__title { font-size: clamp(40px, 6.4vw, 78px); line-height: .98; letter-spacing: -.02em; margin: 0; max-width: 11ch; }
.hero2__lead { font-size: 19px; color: var(--muted); margin: 0 0 14px; max-width: 32em; }
.hero2__diag { display: inline-block; font-weight: 600; color: var(--accent); text-decoration-thickness: 2px; }
.hero2__ask { font-weight: 600; margin: 0 0 12px; }
/* Le nuancier : la signature du site. Une seule rangée qui va du raide au crépu. */
.spectrum { list-style: none; margin: 0 0 20px; padding: 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 0; border: 1.5px solid var(--fg); border-radius: 22px; overflow: hidden; background: var(--surface); }
.spectrum li + li { border-left: 1.5px solid var(--fg); }
.spectrum__item { display: flex; flex-direction: column; gap: 4px; padding: 20px 18px 22px; height: 100%; text-decoration: none; color: var(--fg); transition: background .15s ease; }
.spectrum__item img { width: 100%; max-width: 132px; height: auto; aspect-ratio: 1; margin: 0 0 12px; }
.spectrum__item strong { font-family: var(--display); font-size: 24px; line-height: 1.1; }
.spectrum__item span { font-size: 14px; color: var(--muted); }
.spectrum__item:hover, .spectrum__item:focus-visible { background: var(--accent-soft); color: var(--fg); }
.quick { display: flex; gap: 10px; align-items: end; flex-wrap: wrap; padding: 14px; background: var(--surface); border: 1px solid var(--line); border-radius: 18px; }
.quick__field { display: flex; flex-direction: column; gap: 4px; font-size: 13px; font-weight: 600; color: var(--muted); min-width: 150px; }
.quick__field--grow { flex: 1; min-width: 200px; }
.quick select, .quick input { font: inherit; font-size: 16px; color: var(--fg); min-height: 48px; border: 1.5px solid var(--line); border-radius: 12px; background: var(--bg); padding: 0 12px; }
@media (max-width: 860px) {
  .hero2 { padding-top: 28px; }
  .hero2__top { grid-template-columns: 1fr; gap: 16px; }
  .spectrum { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; border-radius: 18px; }
  .spectrum li { flex: 0 0 42%; scroll-snap-align: start; }
  .quick { flex-direction: column; align-items: stretch; }
}

.section { padding: 56px 0; }
.section--alt { background: var(--surface); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.section__title { margin-bottom: 28px; }
/* Étapes : une vraie suite, numérotée par la liste elle-même. */
.steps2 { list-style: none; counter-reset: step; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 32px; }
.steps2 li { counter-increment: step; border-top: 3px solid var(--accent); padding-top: 18px; }
.steps2 li::before { content: counter(step); display: block; font-family: var(--display); font-size: 44px; line-height: 1; color: var(--accent); margin-bottom: 10px; }
.steps2 p { color: var(--muted); margin: 0; }
.diff__list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px 48px; margin: 0; }
.diff__list dt { font-family: var(--display); font-size: 21px; font-weight: 700; margin-bottom: 6px; }
.diff__list dd { margin: 0; color: var(--muted); max-width: 34em; }
.pro-grid { list-style: none; padding: 0; margin: 0 0 24px; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; }
.pro-card { display: flex; flex-direction: column; background: var(--surface); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; text-decoration: none; color: var(--fg); height: 100%; }
.pro-card:hover { border-color: var(--accent); color: var(--fg); }
.pro-card > img { width: 100%; height: 200px; object-fit: cover; display: block; }
.pro-card__ph { display: flex; gap: 0; height: 160px; background: var(--accent-soft); align-items: center; justify-content: center; padding: 16px; }
.pro-card__ph img { width: 30%; max-width: 110px; }
.pro-card__body { display: flex; flex-direction: column; gap: 6px; padding: 16px; color: var(--muted); font-size: 15px; }
.pro-card__body strong { color: var(--fg); font-size: 18px; }
.pro-card__price { color: var(--accent); font-weight: 600; }
.section--guide { background: var(--gold-soft); }
.guide-teaser { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 40px; align-items: center; }
.guide-teaser p { color: var(--muted); max-width: 30em; }
.guide-teaser__list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }
.guide-teaser__list a { display: flex; align-items: center; gap: 14px; padding: 8px 14px 8px 8px; border-radius: 14px; background: var(--surface); color: var(--fg); text-decoration: none; font-weight: 600; }
.guide-teaser__list a:hover { box-shadow: inset 0 0 0 1.5px var(--gold); }
.guide-teaser__list img { width: 44px; height: 44px; border-radius: 10px; background: var(--bg); padding: 4px; }
.pro-cta { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; background: var(--accent); color: #fff; border-radius: 24px; padding: 40px; }
.pro-cta h2 { color: #fff; }
.pro-cta p { color: rgba(255, 255, 255, .88); margin: 0; max-width: 36em; }
.faq details { border-bottom: 1px solid var(--line); padding: 4px 0; }
.faq summary { cursor: pointer; font-weight: 600; font-size: 18px; padding: 14px 0; list-style-position: outside; }
.faq details p { color: var(--muted); margin: 0 0 16px; }
@media (max-width: 860px) {
  .steps2, .diff__list, .pro-grid, .guide-teaser { grid-template-columns: 1fr; gap: 24px; }
  .pro-cta { padding: 26px; }
}

/* Guide des cheveux */
.guide-nav { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 32px; padding: 0; list-style: none; }
.guide-nav a { display: inline-flex; align-items: center; gap: 8px; padding: 6px 14px 6px 6px; border-radius: 999px; background: var(--surface); border: 1px solid var(--line); text-decoration: none; color: var(--fg); font-weight: 600; }
.guide-nav img { width: 32px; height: 32px; }
.guide-type { display: grid; grid-template-columns: 140px minmax(0, 1fr); gap: 28px; padding: 32px 0; border-top: 1px solid var(--line); scroll-margin-top: 90px; }
.guide-type > img { width: 140px; height: 140px; background: var(--surface); border-radius: 20px; padding: 10px; }
.guide-type h2 { margin-bottom: 8px; }
.guide-type h3 { font-size: 17px; margin: 18px 0 6px; }
.guide-type ul { margin: 0; padding-left: 1.2em; color: var(--muted); }
.guide-type li { margin: 4px 0; }
.guide-type .ask { margin-top: 16px; padding: 12px 16px; border-radius: 14px; background: var(--gold-soft); }
@media (max-width: 640px) { .guide-type { grid-template-columns: 1fr; } .guide-type > img { width: 96px; height: 96px; } }

/* Pages */
.site-main .page { padding: 40px 20px 64px; }
.page__title { margin-bottom: 24px; }
.app-page { padding-top: 8px; padding-bottom: 48px; }
.entry > * + * { margin-top: 1em; }
.entry h2 { margin-top: 1.6em; }
.entry ul, .entry ol { padding-left: 1.3em; }
.entry .wp-block-buttons { margin-top: 1.5em; }
.post-item { padding: 20px 0; border-bottom: 1px solid var(--line); }
.post-item__meta { color: var(--muted); font-size: 14px; }

/* Pied de page */
.site-footer { background: var(--fg); color: #E9E1D9; padding: 40px 0 24px; margin-top: 40px; }
.site-footer a { color: #fff; text-decoration: none; }
.site-footer a:hover { text-decoration: underline; color: #fff; }
.site-footer__inner { display: flex; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
.site-footer__brand { font-family: var(--display); font-weight: 700; font-size: 22px; color: #fff; margin: 0; }
.site-footer__tag { color: #BDB1A7; margin: 4px 0 0; }
.site-footer .menu { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 10px 22px; }
.site-footer__legal { margin-top: 28px; padding-top: 18px; border-top: 1px solid rgba(255,255,255,.12); }
.site-footer__legal .menu a { color: #BDB1A7; font-size: 14px; }
.site-footer__copy { color: #BDB1A7; font-size: 14px; margin-top: 14px; }

/* Les onglets de l'application restent visibles sous l'en-tête collant du site. */
.app-page .cm-app .top { top: 70px; }
.admin-bar .app-page .cm-app .top { top: 102px; }
@media (max-width: 782px) { .admin-bar .app-page .cm-app .top { top: 116px; } }
.entry .guide-nav { padding: 0; }
.entry .guide-type h2 { margin-top: 0; }
.entry .guide-type > img { margin-top: 0; }

/* ---------------- Piste « signature » ---------------- */
.hero3 { position: relative; background: var(--ink); color: var(--on-ink); overflow: hidden; padding-top: 96px; }
.hero3__strands { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.hero3__inner { position: relative; display: flex; flex-direction: column; gap: 26px; padding-top: 56px; padding-bottom: 56px; }
.hero3__title { font-size: clamp(48px, 8vw, 104px); line-height: .95; max-width: 9.5ch; margin: 0; color: var(--on-ink); }
.hero3__lead { font-size: 20px; line-height: 1.55; color: #C9D6D2; max-width: 31em; margin: 0; }
.hero3__search { display: flex; width: 100%; align-items: stretch; gap: 0; background: var(--paper); border-radius: 999px; padding: 6px; max-width: 640px; }
.hero3__field { flex: 0 1 200px; min-width: 0; display: flex; flex-direction: column; justify-content: center; padding: 4px 20px; font-size: 12px; font-weight: 700; color: var(--muted); border-right: 1px solid var(--line); }
.hero3__field--grow { flex: 1 1 auto; border-right: 0; }
.hero3__field select, .hero3__field input { border: 0; background: transparent; font: inherit; font-size: 17px; font-weight: 500; color: var(--fg); padding: 2px 0; min-height: 28px; min-width: 0; }
.hero3__search button { border: 0; border-radius: 999px; background: var(--gold); color: var(--ink); font: inherit; font-weight: 700; font-size: 16px; padding: 0 26px; min-height: 56px; cursor: pointer; white-space: nowrap; flex: 0 0 auto; }
.hero3__search button:hover { background: #EDCB86; }
.hero3__diag { color: var(--gold); font-weight: 600; text-decoration-thickness: 1.5px; align-self: flex-start; }
.hero3__diag:hover { color: #F3D79A; }
.hero3__types { position: relative; list-style: none; margin: 0 auto; padding-top: 0; padding-bottom: 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); border-top: 1px solid rgba(240, 242, 238, .18); }
.hero3__types li + li { border-left: 1px solid rgba(240, 242, 238, .18); }
.hero3__types a { display: flex; flex-direction: column; gap: 2px; padding: 22px 18px 26px; color: var(--on-ink); text-decoration: none; transition: background .15s ease; }
.hero3__types li:first-child a { padding-left: 0; }
.hero3__types a:hover, .hero3__types a:focus-visible { background: rgba(240, 242, 238, .06); color: var(--gold); }
.hero3__types strong { font-family: var(--serif); font-weight: 400; font-size: 28px; line-height: 1.1; }
.hero3__types span { font-size: 14px; color: var(--on-ink-muted); }
@media (max-width: 860px) {
  .hero3 { padding-top: 76px; }
  .hero3__search { flex-direction: column; border-radius: 22px; }
  .hero3__field, .hero3__field--grow { flex: none; border-right: 0; border-bottom: 1px solid var(--line); padding: 10px 14px; }
  .hero3__search button { margin-top: 6px; }
  .hero3__types { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; }
