  .hero3__types li:first-child a { padding-left: 18px; }
}
.soon { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.5fr); gap: 56px; align-items: start; }
.soon__title { font-size: clamp(34px, 4.4vw, 54px); }
.soon__lead { color: var(--muted); max-width: 26em; }
.soon__list { list-style: none; margin: 0; padding: 0; }
.soon__list li { border-top: 1px solid var(--line); }
.soon__list li:last-child { border-bottom: 1px solid var(--line); }
.soon__list a { display: grid; grid-template-columns: 76px minmax(0, 1fr) auto; gap: 18px; align-items: center; padding: 16px 0; color: var(--fg); text-decoration: none; }
.soon__list a:hover .soon__slot { background: var(--accent); }
.soon__ph { width: 76px; height: 76px; border-radius: 999px; object-fit: cover; background: var(--accent-soft); }
.soon__ph--tex { display: grid; place-items: center; }
.soon__ph--tex img { width: 64%; }
.soon__who { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.soon__who strong { font-size: 19px; }
.soon__who span { color: var(--muted); font-size: 15px; }
.soon__slot { padding: 10px 16px; border-radius: 999px; background: var(--ink); color: var(--on-ink); font-weight: 700; white-space: nowrap; transition: background .15s ease; }
@media (max-width: 860px) { .soon { grid-template-columns: 1fr; gap: 20px; } .soon__list a { grid-template-columns: 56px minmax(0, 1fr); } .soon__ph { width: 56px; height: 56px; } .soon__slot { grid-column: 2; justify-self: start; padding: 6px 12px; font-size: 14px; } }
.steps2 li { border-top-color: var(--ink); }
.steps2 li::before { font-family: var(--serif); color: var(--ink); font-size: 52px; }
.diff__list dt { font-family: var(--serif); font-weight: 400; font-size: 26px; }
.section--guide { background: var(--gold-soft); }
.guide-teaser__list a:hover { box-shadow: inset 0 0 0 1.5px var(--gold-ink); }
.pro-cta { background: var(--ink); }
.pro-cta .btn--light { background: var(--gold); border-color: var(--gold); color: var(--ink) !important; }
.site-footer { background: var(--ink); }
.site-footer__brand { font-family: var(--serif); font-weight: 400; font-size: 26px; }
/* Menu du compte (cliente connectée) */
.acct { position: relative; }
.acct > summary { list-style: none; display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 14px 0 5px; border-radius: 999px; border: 1.5px solid rgba(240, 242, 238, .3); color: var(--on-ink); font-weight: 600; cursor: pointer; }
.acct > summary::-webkit-details-marker { display: none; }
.acct__av { display: inline-grid; place-items: center; width: 32px; height: 32px; border-radius: 999px; background: var(--gold); color: var(--ink); font-weight: 700; }
.acct__menu { position: absolute; right: 0; top: calc(100% + 8px); min-width: 230px; background: var(--surface); color: var(--fg); border: 1px solid var(--line); border-radius: 16px; padding: 8px; box-shadow: 0 18px 40px -18px rgba(11, 42, 39, .45); list-style: none; margin: 0; z-index: 60; }
.acct__menu a { display: block; padding: 10px 12px; border-radius: 10px; color: var(--fg); text-decoration: none; }
.acct__menu a:hover { background: var(--accent-soft); }
.acct__menu li.sep { border-top: 1px solid var(--line); margin-top: 6px; padding-top: 6px; }
@media (max-width: 860px) { .acct__menu { position: static; box-shadow: none; margin-top: 8px; } }

/* Boutons du site : encre et pilule, comme l'accueil */
.btn, .wp-block-button__link { background: var(--ink); border-color: var(--ink); border-radius: 999px; }
.btn:hover, .wp-block-button__link:hover { background: var(--ink-2); border-color: var(--ink-2); }
.btn--small { border-radius: 999px; }
.btn--ghost { background: transparent; border-color: var(--ink); color: var(--ink) !important; }
.btn--ghost:hover { background: var(--ink); color: var(--on-ink) !important; }
.site-footer__tag { color: var(--on-ink-muted); }
.site-footer__legal .menu a, .site-footer__copy { color: var(--on-ink-muted); }

/* Bandeau des pages intérieures : la nuit et les mèches de l'accueil, en plus court */
.band { position: relative; background: var(--ink); color: var(--on-ink); overflow: hidden; }
.band__inner { position: relative; padding-top: 56px; padding-bottom: 60px; }
.band__title { color: var(--on-ink); font-size: clamp(42px, 6.4vw, 76px); line-height: .98; margin: 0; max-width: 14ch; }
.band__lead { color: #C9D6D2; font-size: 19px; max-width: 32em; margin: 18px 0 0; }
.site-main .band + .page { padding-top: 44px; }
@media (max-width: 860px) { .band__inner { padding-top: 36px; padding-bottom: 40px; } }

/* Contenu des pages */
.entry { font-size: 18px; }
.entry h2 { font-size: clamp(28px, 3vw, 36px); }
.entry ul:not(.guide-nav) { list-style: none; padding-left: 0; }
.entry ul:not(.guide-nav) > li { position: relative; padding-left: 26px; margin: 8px 0; }
.entry ul:not(.guide-nav) > li::before { content: ""; position: absolute; left: 2px; top: .62em; width: 12px; height: 2px; border-radius: 2px; background: var(--gold); }
.entry ol { padding-left: 1.3em; }
.entry ol li::marker { font-family: var(--serif); color: var(--gold-ink); }
.entry blockquote { margin: 1.4em 0; padding: 18px 22px; border-radius: 18px; background: var(--gold-soft); }
.guide-type ul > li::before { display: none; }
.guide-type ul { list-style: disc; padding-left: 1.2em !important; }
.guide-type ul > li { padding-left: 0 !important; }
.guide-type > img { border: 1px solid var(--line); }
.guide-nav a { border-radius: 999px; }
.guide-nav a:hover { border-color: var(--ink); }
.guide-type .ask { border-left: 3px solid var(--gold); }
#comment-ca-marche { scroll-margin-top: 90px; }
.site-footer__types { margin-top: 28px; }
.site-footer__h { color: var(--on-ink-muted); font-size: 14px; font-weight: 600; margin: 0 0 8px; }
.site-footer__types .menu a { font-size: 15px; }
.cm-public .site-main { min-height: 0; }
.brand__mark { background: none; width: 36px; height: 36px; }
.brand__mark svg { width: 100%; height: 100%; display: block; }

/* Page « Devenir coiffeur partenaire » */
.band--pro .band__title { max-width: 16ch; }
.band__cta { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; margin: 24px 0 0; }
.btn--gold { background: var(--gold) !important; border-color: var(--gold) !important; color: var(--ink) !important; }
.btn--gold:hover { background: #EDCB86 !important; }
.band__link { color: var(--on-ink); font-weight: 600; }
.band__link:hover { color: var(--gold); }
.pfacts { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 1px solid var(--line); }
.pfacts li { display: flex; flex-direction: column; gap: 4px; padding: 22px 20px 6px 0; }
.pfacts li + li { padding-left: 20px; border-left: 1px solid var(--line); }
.pfacts strong { font-family: var(--serif); font-weight: 400; font-size: clamp(40px, 5vw, 60px); line-height: 1; }
.pfacts span { color: var(--muted); }
.pmock-wrap { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr); gap: 40px; align-items: center; }
.pmock-wrap p { color: var(--muted); max-width: 30em; }
.pmock { position: relative; margin: 0; display: grid; grid-template-columns: 150px minmax(0, 1fr); gap: 12px; padding: 12px; border-radius: 22px; background: var(--surface); box-shadow: 0 24px 50px -30px rgba(11, 42, 39, .55); font-size: 14px; }
.pmock__side { display: flex; flex-direction: column; gap: 4px; padding: 10px; border-radius: 14px; background: var(--ink); color: #DCE6E1; }
.pmock__side span { padding: 8px 10px; border-radius: 8px; }
.pmock__on { background: var(--gold); color: var(--ink); font-weight: 700; }
.pmock__main { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.pmock__stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.pmock__stats span { display: flex; flex-direction: column; padding: 10px; border-radius: 12px; border: 1px solid var(--line); color: var(--muted); font-size: 12px; }
.pmock__stats b { font-size: 20px; color: var(--fg); }
.pmock__row { padding: 10px 12px; border-radius: 10px; border: 1.5px dashed var(--line); color: var(--muted); }
.pmock__row b { color: var(--fg); margin-right: 6px; }
.pmock__row--ok { border: 0; border-left: 4px solid var(--ok); background: var(--ok-soft); color: var(--fg); }
.pmock__row--warn { border: 0; border-left: 4px solid var(--warm); background: var(--warm-soft); color: var(--fg); }
.pmock figcaption { position: absolute; right: 16px; bottom: -26px; font-size: 12px; color: var(--muted); }
@media (max-width: 860px) {
  .pfacts { grid-template-columns: 1fr 1fr; }
  .pfacts li:nth-child(3) { padding-left: 0; border-left: 0; }
  .pmock-wrap { grid-template-columns: 1fr; }
  .pmock { grid-template-columns: 1fr; }
  .pmock__side { flex-direction: row; overflow-x: auto; }
  .pmock__side span { white-space: nowrap; }
}
/* Les listes des formulaires et de l'application ne prennent pas les tirets dorés du contenu. */
.entry :is(.cm-account, .cm-app, .cm-legal, .cm-door, .cm-delete) ul > li { padding-left: 0; }
.entry :is(.cm-account, .cm-app, .cm-door, .cm-delete) ul > li::before { display: none; }
.entry .cm-account__links { display: flex; flex-wrap: wrap; gap: 10px; }
.entry .cm-account__links > li { margin: 0; }
.entry .cm-door { padding-top: 0; }

/* ---------------- Fluidité ---------------- */
@media (prefers-reduced-motion: no-preference) {
  /* Un seul moment orchestré : l'entrée de l'accueil. */
  .hero3__title, .hero3__lead, .hero3__search, .hero3__diag, .hero3__types li { animation: cmUp .7s cubic-bezier(.2, .7, .2, 1) both; }
  .hero3__lead { animation-delay: .12s; } .hero3__search { animation-delay: .22s; } .hero3__diag { animation-delay: .3s; }
  .hero3__types li { animation-delay: .38s; } .hero3__types li:nth-child(2) { animation-delay: .44s; } .hero3__types li:nth-child(3) { animation-delay: .5s; }
  .hero3__types li:nth-child(4) { animation-delay: .56s; } .hero3__types li:nth-child(5) { animation-delay: .62s; }
  .btn, .hero3__search button, .soon__slot, .site-nav__account { transition: background-color .15s ease, color .15s ease, transform .12s ease; }
  .btn:active, .hero3__search button:active { transform: scale(.98); }
  .site-header { transition: background-color .25s ease, border-color .25s ease, box-shadow .25s ease; }
}
@keyframes cmUp { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: none; } }
.home .site-header.is-solid { position: fixed; background: var(--ink); border-bottom-color: rgba(240, 242, 238, .12); box-shadow: 0 10px 30px -20px rgba(0, 0, 0, .6); }
.admin-bar.home .site-header.is-solid { top: 32px; }
.hero3__search:focus-within { box-shadow: 0 0 0 4px rgba(226, 184, 100, .45); }
.hero3__types a strong { transition: transform .2s ease; }
@media (hover: hover) { .hero3__types a:hover strong { transform: translateX(4px); } .soon__list a:hover .soon__ph { transform: scale(1.04); } }
.soon__ph { transition: transform .25s ease; }

/* Reprendre où vous en étiez */
.recent-home { background: var(--surface); border-bottom: 1px solid var(--line); }
.recent-home__inner { display: flex; align-items: center; gap: 18px; padding-top: 16px; padding-bottom: 16px; flex-wrap: wrap; }
.recent-home__t { margin: 0; font-weight: 700; }
.recent-home__row { display: flex; gap: 10px; overflow-x: auto; flex: 1; min-width: 0; }
.recent-home__it { flex: none; display: flex; align-items: center; gap: 10px; padding: 6px 16px 6px 6px; border-radius: 999px; border: 1px solid var(--line); text-decoration: none; color: var(--fg); background: var(--bg); }
.recent-home__it:hover { border-color: var(--ink); color: var(--fg); }
.recent-home__it img { width: 38px; height: 38px; border-radius: 999px; object-fit: cover; background: #E3EAE6; }
.recent-home__it img.t { object-fit: contain; padding: 5px; }
.recent-home__it span { display: flex; flex-direction: column; line-height: 1.2; }
.recent-home__it strong { font-size: 14px; } .recent-home__it small { font-size: 12px; color: var(--muted); }
.entry .cm-door h2 { margin-top: 0; }

/* Le doré est réservé à la recherche et à la réservation. */
.section--guide { background: var(--surface); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.site-nav__account { background: transparent !important; border: 1.5px solid rgba(240, 242, 238, .45) !important; color: var(--on-ink) !important; }
.site-nav__account:hover { background: rgba(240, 242, 238, .1) !important; border-color: var(--on-ink) !important; }
.soon__slot { background: var(--gold); color: var(--ink); }
.soon__list a:hover .soon__slot { background: #EDCB86; }
.guide-type .ask { background: var(--surface); }
.acct > summary.has-unread .acct__av { box-shadow: 0 0 0 2px var(--ink), 0 0 0 4px var(--gold); }

/* ---------------- Accueil : les textures ---------------- */
.textures__head { display: flex; justify-content: space-between; align-items: end; gap: 24px; flex-wrap: wrap; margin-bottom: 26px; }
.textures__head h2 { margin: 0; max-width: 12ch; font-size: clamp(34px, 4.4vw, 54px); }
.textures__head p { margin: 0; color: var(--muted); max-width: 26em; }
.textures__list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 14px; }
.textures__list a { position: relative; display: block; aspect-ratio: 3 / 4.4; border-radius: 22px; overflow: hidden; color: #F0F2EE; text-decoration: none; background: var(--ink); isolation: isolate; }
.textures__list img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: -2; transition: transform .6s cubic-bezier(.2, .7, .2, 1); }
.textures__list a::after { content: ""; position: absolute; inset: 0; z-index: -1; background: linear-gradient(180deg, rgba(11, 42, 39, 0) 30%, rgba(11, 42, 39, .92) 100%); }
.textures__body { position: absolute; left: 0; right: 0; bottom: 0; display: flex; flex-direction: column; gap: 4px; padding: 18px; }
.textures__body strong { font-family: var(--serif); font-weight: 400; font-size: 32px; line-height: 1; }
.textures__n { font-weight: 700; color: var(--gold); font-size: 14px; }
.textures__ask { font-size: 13px; line-height: 1.4; color: #C9D6D2; max-height: 0; overflow: hidden; opacity: 0; transition: max-height .35s ease, opacity .25s ease; }
@media (hover: hover) {
  .textures__list a:hover img { transform: scale(1.06); }
  .textures__list a:hover .textures__ask, .textures__list a:focus-visible .textures__ask { max-height: 80px; opacity: 1; }
}
@media (hover: none) { .textures__ask { max-height: none; opacity: 1; } }
@media (max-width: 900px) {
  .textures__list { display: flex; overflow-x: auto; scroll-snap-type: x mandatory; padding-bottom: 6px; }
  .textures__list li { flex: 0 0 62%; scroll-snap-align: start; }
}

/* La promesse */
.promise { background: var(--ink); color: var(--on-ink); }
.promise__inner { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr); gap: 28px 56px; align-items: start; }
.promise__big { grid-row: span 2; margin: 0; font-family: var(--serif); font-size: clamp(36px, 4.6vw, 60px); line-height: 1.02; letter-spacing: -.01em; text-wrap: balance; }
.promise__path { list-style: none; counter-reset: p; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0; }
.promise__path li { counter-increment: p; display: grid; grid-template-columns: 44px minmax(0, 1fr); column-gap: 14px; padding: 14px 0; border-top: 1px solid rgba(240, 242, 238, .16); }
.promise__path li::before { content: counter(p); grid-row: span 2; font-family: var(--serif); font-size: 34px; line-height: 1; color: var(--gold); }
.promise__path strong { font-size: 18px; }
.promise__path span { color: var(--on-ink-muted); }
.promise__proofs { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: 1fr 1fr; gap: 14px 24px; }
.promise__proofs li { position: relative; padding-left: 22px; color: #C9D6D2; font-size: 15px; }
.promise__proofs li::before { content: "✓"; position: absolute; left: 0; color: var(--gold); font-weight: 700; }
@media (max-width: 860px) { .promise__inner { grid-template-columns: 1fr; } .promise__big { grid-row: auto; } .promise__proofs { grid-template-columns: 1fr; } }

/* Contact en deux colonnes */
.contact2 { display: grid; grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); gap: 48px; padding-top: 44px; padding-bottom: 64px; align-items: start; }
.contact2__info { display: flex; flex-direction: column; gap: 22px; }
.contact2__info h2 { font-size: 30px; margin: 0 0 6px; }
.contact2__info h3 { font-size: 17px; margin: 0 0 4px; }
.contact2__info p { margin: 0 0 4px; color: var(--muted); }
.contact2__info > div + div { padding-top: 20px; border-top: 1px solid var(--line); }
.contact2__form .cm-form { max-width: none; }
@media (max-width: 860px) { .contact2 { grid-template-columns: 1fr; gap: 28px; } }

/* Pages légales avec sommaire */
.legal2 { display: grid; grid-template-columns: 240px minmax(0, 760px); gap: 56px; justify-content: start; padding-top: 44px; padding-bottom: 64px; }
.legal2__toc { position: sticky; top: 96px; align-self: start; }
.legal2__toc p { font-weight: 700; margin: 0 0 10px; }
.legal2__toc ol { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; border-left: 2px solid var(--line); }
.legal2__toc a { display: block; padding: 6px 12px; margin-left: -2px; border-left: 2px solid transparent; color: var(--muted); text-decoration: none; font-size: 15px; }
.legal2__toc a:hover { color: var(--fg); border-left-color: var(--ink); }
.site-main .legal2__text { padding: 0; }
.legal2 h2 { scroll-margin-top: 90px; }
@media (max-width: 860px) { .legal2 { grid-template-columns: 1fr; gap: 20px; } .legal2__toc { position: static; } }

/* Les coiffeurs, avec leurs mots */
.voices__title { margin-bottom: 24px; }
.voices__list { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
.voices__list a { display: flex; flex-direction: column; justify-content: space-between; gap: 20px; height: 100%; padding: 24px; border-radius: 22px; background: var(--surface); border: 1px solid var(--line); color: var(--fg); text-decoration: none; transition: border-color .15s ease, transform .2s ease; }
@media (hover: hover) { .voices__list a:hover { border-color: var(--ink); transform: translateY(-2px); } }
.voices__list blockquote { margin: 0; font-family: var(--serif); font-size: 22px; line-height: 1.3; }
.voices__who { display: flex; align-items: center; gap: 12px; }
.voices__who img { width: 44px; height: 44px; border-radius: 999px; object-fit: cover; }
.voices__who span { display: flex; flex-direction: column; line-height: 1.25; }
.voices__who small { color: var(--muted); }
@media (max-width: 860px) { .voices__list { grid-template-columns: 1fr; } }
/* L'appel aux coiffeurs, en clair pour ne pas coller au bloc sombre de la promesse. */
.pro-cta { background: var(--surface); color: var(--fg); border: 1px solid var(--line); }
.pro-cta h2 { color: var(--fg); }
.pro-cta p { color: var(--muted); }
.pro-cta .btn--light { background: var(--ink) !important; border-color: var(--ink) !important; color: var(--on-ink) !important; }
/* Bandeau et contenu alignés sur la même grille que l'en-tête, sur toutes les pages. */
.site-main .page > .entry { max-width: 760px; }
.cm-progress { position: fixed; left: 0; right: 0; top: 0; height: 3px; z-index: 10000; background: var(--gold); transform-origin: 0 50%; transform: scaleX(0); opacity: 0; pointer-events: none; }
.admin-bar .cm-progress { top: 32px; }
@media (prefers-reduced-motion: reduce) { .cm-progress { transition: none !important; } }
.site-nav__admin { background: #8A4B12 !important; border-color: #8A4B12 !important; color: #fff !important; border-radius: 999px !important; }
.site-nav__admin::before { content: "●"; color: #F3C37A; margin-right: 8px; font-size: 10px; }
.site-nav__out { color: var(--on-ink-muted); font-size: 15px; }
.site-nav__out:hover { color: var(--on-ink); }
.brand__pro { margin-left: 8px; padding: 2px 9px; border-radius: 999px; background: var(--gold); color: var(--ink); font: 700 12px/1.4 var(--body); letter-spacing: .02em; align-self: center; }
.brand__pro--team { background: #F3C37A; }

